// @exec: {"yield_time_ms": 30000, "max_output_tokens": 20000}
const r = await tools.web__run({open:[{ref_id:"https://raw.githubusercontent.com/agent-ecosystem/agent-docs-spec/main/SPEC.md"}],response_length:"long"});
store("ec6_web_result", r);
const raw = JSON.stringify(r);
const blocks = Array.isArray(r?.content) ? r.content : [];
const textParts = blocks.filter(b => b?.type === "text").map(b => b.text ?? "");
const body = textParts.join("\n");
store("ec6_body", body);
const fenceCount = (body.match(/^```/gm) || []).length;
const indicators = ["truncated","truncation","omitted","clipped","cut off","maximum","too large","content limit","[..."];
const matches = indicators.filter(x => body.toLowerCase().includes(x));
text(JSON.stringify({
  top_level_keys: Object.keys(r ?? {}),
  content_blocks: blocks.map(b => ({type:b?.type, chars:typeof b?.text === "string" ? b.text.length : null, keys:Object.keys(b ?? {})})),
  wrapper_chars: raw.length,
  extracted_text_chars: body.length,
  estimated_tokens_chars_div_4: Math.ceil(body.length / 4),
  last_50: body.slice(-50),
  fence_count: fenceCount,
  fenced_code_blocks_closed: fenceCount % 2 === 0,
  truncation_indicator_matches: matches,
  trailing_500: body.slice(-500),
  raw_result_tail: raw.slice(-1000)
}, null, 2));

const body = load("ec6_web_result");
const lines = body.split("\n");
const cleanLines = lines.map(line => line.replace(/^L\d+:\s?/, ""));
const clean = cleanLines.join("\n");
const fenceLines = lines
  .map((line, i) => ({line: i + 1, text: line}))
  .filter(x => /^L\d+:\s*```/.test(x.text));
const headings = lines
  .filter(line => /^L\d+:\s*#{1,6}\s+/.test(line))
  .slice(-10);
const numbered = lines.map(line => /^L(\d+):/.exec(line)?.[1]).filter(Boolean).map(Number);
const markerTerms = ["truncated", "truncation", "omitted", "clipped", "cut off", "content limit", "maximum"];
const foundMarkers = markerTerms.filter(term => body.toLowerCase().includes(term));
const words = clean.trim().split(/\s+/).filter(Boolean).length;
text(JSON.stringify({
  returned_type: typeof body,
  response_characters: body.length,
  response_lines: lines.length,
  displayed_source_line_range: numbered.length ? {first:numbered[0],last:numbered[numbered.length-1],count:numbered.length} : null,
  estimated_tokens_char_div_4: Math.ceil(body.length/4),
  word_count: words,
  alternate_token_estimate_words_x_1_3: Math.ceil(words*1.3),
  last_50_characters_json_escaped: JSON.stringify(body.slice(-50)),
  last_500_characters_json_escaped: JSON.stringify(body.slice(-500)),
  explicit_truncation_markers: foundMarkers,
  fence_lines: fenceLines,
  fence_count: fenceLines.length,
  fences_even_and_closed_in_returned_view: fenceLines.length % 2 === 0,
  last_headings: headings,
  first_300_characters_json_escaped: JSON.stringify(body.slice(0,300))
}, null,2));

const body = load("ec6_web_result");
const payloadStart = body.indexOf("L0:");
const payload = payloadStart >= 0 ? body.slice(payloadStart) : "";
const totalLinesMatch = /Total lines:\s*(\d+)/.exec(body);
const fenceCount = (body.match(/```/g) || []).length;
const endLine = /(?:^|\n)L(\d+):[^\n]*$/.exec(body)?.[1] ?? null;
const terminalLine = body.split("\n").at(-2) ?? "";
const prefix = body.slice(0, payloadStart).replace(/\n/g, "\\n");
text(JSON.stringify({
  returned_characters: body.length,
  payload_characters_including_L_labels: payload.length,
  tool_metadata_prefix: prefix,
  declared_total_source_lines: totalLinesMatch?.[1] ?? null,
  final_returned_source_line: endLine,
  final_returned_line_verbatim_json_escaped: JSON.stringify(terminalLine),
  triple_backtick_delimiter_count: fenceCount,
  triple_backticks_balanced: fenceCount % 2 === 0,
  last_50: body.slice(-50),
  last_50_json_escaped: JSON.stringify(body.slice(-50))
}, null, 2));
